//! The Android emulator's gRPC client, generated by script/gen-android-grpc.sh
//! from proto/android/emulator_controller.proto. Not part of the build.

// Generated code: not ours to lint, and much of it unused.
#[allow(clippy::all, dead_code, unused)]
mod generated {
    include!("android.emulation.control.rs");
}

pub(crate) use generated::*;

/// Largest gRPC reply the client accepts. A full RGBA frame of a phone is
/// 10.4 MB, a 4K TV's 33 MB, all above tonic's 4 MiB default; the call is
/// to localhost. The stream never asks for a frame bigger than this
/// (`stream::request_box`).
pub(crate) const MAX_DECODING_MESSAGE_SIZE: usize = 64 * 1024 * 1024;
